"""Create a local comparison of the actual delivered sample renders and plans."""
from pathlib import Path
import json
import sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
out=ROOT/'output/tirumala-luxury-review'
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tirumala 2 + 3 · Updated homes</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f3ed;color:#273d33;font:15px Arial,sans-serif}main{max-width:1700px;margin:auto;padding:34px}header{display:flex;justify-content:space-between;align-items:end;gap:50px}.eyebrow{font-size:11px;letter-spacing:2px;color:#7e7b6f}h1{font-size:33px;font-weight:500;margin:13px 0}header p{line-height:1.6;max-width:500px;color:#667064;font-size:13px}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:25px 0}button{padding:12px 16px;border:1px solid #d2d1c7;border-radius:6px;background:#fffefa;color:#344c3b;cursor:pointer;font-size:13px}button[aria-pressed=true]{background:#344c3b;color:white;border-color:#344c3b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}article{background:#fffdfa;border:1px solid #ddd9ce;border-radius:8px;overflow:hidden}.title{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:18px 20px}h2{font-size:21px;margin:0;font-weight:500}.title span{font-size:12px;color:#7b7565}img{width:100%;height:auto;display:block}.facts{padding:18px 20px;font-size:13px;line-height:1.65;border-top:1px solid #e7e2d7;color:#657060}footer{display:flex;justify-content:space-between;gap:30px;font-size:13px;line-height:1.6;margin-top:25px}a{color:#385d48}#caption{font-size:13px;color:#6c7368;margin:14px 0 24px}@media(max-width:850px){.grid{grid-template-columns:1fr}header,footer{display:block}main{padding:18px}}</style>
<main><header><div><div class="eyebrow">TIRUMALA 2 + 3 · UPDATED SAMPLE PROJECTS</div><h1>More space to move.</h1></div><p>40 × 50 ft · Actual scale retained.<br>P13 extends the ICU 2 ft east, retaining a 5 ft forecourt. Soft ivory finishes, neutral-warm lighting and improved room views throughout both homes.</p></header>
<div class="controls" aria-label="Choose comparison view"><button data-view="exterior-northeast.png" aria-pressed="true">Exterior</button><button data-view="plan-2d-dimensioned.png">Ground floor · feet</button><button data-view="plan-first-floor.png">First floor · feet</button><button data-view="interior-icu-veranda-garden.png">Inside the ICU</button><button data-view="icu-door-wood-closed.png">ICU · wood closed</button><button data-view="icu-door-glass-revealed.png">ICU · glass revealed</button><button data-view="icu-door-both-open.png">ICU · both open</button><button data-view="interior-veranda-living.png">Veranda</button><button data-view="interior-master.png">Master bedroom</button><button data-view="interior-drawing.png">Drawing room</button><button data-view="upper-gallery.png">Gallery over living</button><button data-view="upper-terrace.png">Open terrace</button><button data-view="interior-kitchen-living-dining.png">Kitchen + living</button></div>
<div class="grid"><article><div class="title"><h2>Tirumala 2</h2><span>P12 · compact storage</span></div><img id="t2" src="../../examples/gallery/tirumala-2/renders/exterior-northeast.png" alt="Tirumala 2 exterior"><div class="facts"><strong>ICU @@ICU2@@</strong><br>Front veranda beside kitchen · drawing room empty · existing ICU footprint retained.<br><a href="../../examples/gallery/tirumala-2/preview.html">Walk through Tirumala 2</a></div></article><article><div class="title"><h2>Tirumala 3</h2><span>P13 · revised from P11</span></div><img id="t3" src="../../examples/gallery/tirumala-3/renders/exterior-northeast.png" alt="Tirumala 3 exterior"><div class="facts"><strong>ICU @@ICU3@@</strong><br>2 ft east extension · 5 ft forecourt · one companion chair and compact storage.<br><a href="../../examples/gallery/tirumala-3/preview.html">Walk through Tirumala 3</a></div></article></div>
<p id="caption">Actual real-time model views. Ivory, limestone, warm teak and charcoal are applied to both samples.</p>
<footer><div><a href="../tirumala-spacious-gallery/CHANGES.txt">Changes and validation</a><br>Run <code>bash start.sh</code>, then open <strong>Sample projects</strong> and select Tirumala 2 or 3.<br>G+1 enclosed rooms, stairs, kitchen, veranda and parking remain in place. P13's terrace extends over the added ICU footprint.</div><div><a href="../../examples/gallery/tirumala-2/FloorForge-export.zip">Download Tirumala 2 package</a> · <a href="../../examples/gallery/tirumala-3/FloorForge-export.zip">Download Tirumala 3 package</a><br><a href="../tirumala-icu-trials/index.html">Tirumala 2 alternative trials</a></div></footer></main>
<script>const captions={'icu-door-wood-closed.png':'From the living hall, the wooden privacy door is in front and conceals the glass slider behind it.','icu-door-glass-revealed.png':'The wooden layer is parked aside, revealing the independent sliding glass door in the same entrance.','icu-door-both-open.png':'Both layers are parked beside the same opening, leaving a clear entrance into the ICU.','exterior-northeast.png':'Actual real-time model views. Ivory, limestone, warm teak and charcoal are applied to both samples.','plan-2d-dimensioned.png':'All approved ground-room footprints, wall and opening positions, kitchen counters, stair and furniture footprints are retained. Dimensions are in feet and inches.','plan-first-floor.png':'First-floor master above ground master; office, guest bedroom, bathrooms, gallery and open terrace. Irregular rooms use polygon areas; spans are bounding dimensions.','upper-gallery.png':'The glass gallery looks down into the open living/dining area. Two new arrival risers connect the retained stair to the upper floor.','upper-terrace.png':'Direct access from the upper gallery to the open terrace, with pergola, planting, seating and perimeter guards.','interior-kitchen-living-dining.png':'Kitchen, dining and living remain connected. The L-counter and short serving worktop stay in their approved positions.'};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(q=>q.setAttribute('aria-pressed',q===b));for(const n of [2,3]){const img=document.querySelector('#t'+n);img.src='../../examples/gallery/tirumala-'+n+'/renders/'+b.dataset.view;img.alt='Tirumala '+n+' — '+b.textContent;}document.querySelector('#caption').textContent=captions[b.dataset.view];});</script></html>'''
html=html.replace('All approved ground-room footprints, wall and opening positions, kitchen counters, stair and furniture footprints are retained. Dimensions are in feet and inches.', 'Current dimensioned plans. P13 gains 2 ft of ICU length from the east forecourt; the kitchen, stairs, other ground rooms, veranda and car bay remain in place.')
html=html.replace('P12 · compact storage','P12 · wider ICU')
html=html.replace('existing ICU footprint retained.','1½ ft ICU south extension into open living. Living–veranda doorway: 3′5⅝″ clear.')
html=html.replace('P13 extends the ICU 2 ft east, retaining a 5 ft forecourt.', 'P12 gains 1½ ft south; P13 gains 2 ft east while retaining a 5 ft forecourt.')
html=html.replace('textContent=captions[b.dataset.view];', "textContent=captions[b.dataset.view] || 'Actual eye-level view of the updated model; room and furniture dimensions remain at true scale.';")
from floorforge.tirumala_p11_p12 import _mm_to_ft_in
for n in (2,3):
    b=json.loads((ROOT/f'examples/gallery/tirumala-{n}/building.json').read_text())
    r=next(r for r in b['spaces'] if r['id']=='g-care');x0,y0,x1,y1=r['bounds']
    html=html.replace(f'@@ICU{n}@@',f'{_mm_to_ft_in(x1-x0)} × {_mm_to_ft_in(y1-y0)} · {r["area_m2"]/.09290304:.1f} sq ft'+(' (notched)' if n==2 else ''))
(out/'index.html').write_text(html)
print(out/'index.html')
